const currentTime = new Date($input.item.json.messageTimestamp);
const lastMessageTime = $input.item.json.timestamp ? new Date($input.item.json.timestamp) : null;

if (lastMessageTime) {
  const timeDiff = (currentTime - lastMessageTime) / 1000;
  if (timeDiff < 15) {
    return { isSpam: true, timeDiff, customerPhone: $input.item.json.customerPhone };
  }
}

return { isSpam: false, customerPhone: $input.item.json.customerPhone, messageBody: $input.item.json.messageBody };

const message = $input.item.json.messageBody.toLowerCase();
const escalationKeywords = ["refund", "broken", "complaint", "not working", "defective", "damaged", "angry", "terrible", "worst"];

const hasEscalationKeyword = escalationKeywords.some(keyword => message.includes(keyword));

return {
  customerPhone: $input.item.json.customerPhone,
  messageBody: $input.item.json.messageBody,
  forceEscalation: hasEscalationKeyword
};

const rawTicketId = $input.item.json.body.ticketId || "";
const staffReply = $input.item.json.body.staffReply || "";

let ticketId = null;

const tckPattern = /TCK-\d+-[A-Z0-9]+/i;
const numPattern = /\b\d{10,}\b/;

if (tckPattern.test(rawTicketId)) {
  ticketId = rawTicketId.match(tckPattern)[0].toUpperCase();
} else if (numPattern.test(rawTicketId)) {
  const num = rawTicketId.match(numPattern)[0];
  ticketId = `TCK-${num}`;
} else {
  const combined = rawTicketId + " " + staffReply;
  if (tckPattern.test(combined)) {
    ticketId = combined.match(tckPattern)[0].toUpperCase();
  }
}

return {
  ticketId,
  staffReply,
  rawInput: rawTicketId
};

const hoursThreshold = 24;
const cutoffTime = new Date(Date.now() - hoursThreshold * 60 * 60 * 1000);

return {
  cutoffTime: cutoffTime.toISOString(),
  hoursThreshold
};

